COPY public.content (content_id, document, base_language, created_at, updated_at) FROM stdin;
31db854d-ea94-4b6d-836f-91c36aa2f191	{"00c1956e-60b0-4b70-86ce-23061858d5da": {"id": "00c1956e-60b0-4b70-86ce-23061858d5da", "meta": {"align": "left", "depth": 0, "order": 7}, "type": "BulletedList", "value": [{"id": "85db81bc-600d-432f-ba2b-c1305927104c", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Nhà nghiên cứu/ tư vấn về đổi mới sáng tạo, chuyển đổi kinh tế số và ứng dụng KHMT, toán học tại bộ phận nghiên cứu và phát triển của các công ty/tổ chức;"}]}]}, "1508187d-a087-46c0-b69e-7887df7797e4": {"id": "1508187d-a087-46c0-b69e-7887df7797e4", "meta": {"align": "left", "depth": 0, "order": 4}, "type": "Paragraph", "value": [{"id": "e0dadb45-6061-4fc0-9816-5cd9787cd3fb", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "Sinh viên tốt nghiệp ngành KHMT có thể làm việc ở nhiều vị trí khác nhau, điển hình là các vị trí sau:"}]}]}, "544761ae-49d0-4292-b32a-2415e78923a0": {"id": "544761ae-49d0-4292-b32a-2415e78923a0", "meta": {"align": "left", "depth": 0, "order": 8}, "type": "BulletedList", "value": [{"id": "e083bbdb-4e8f-4f03-a05f-bb8ab34ad45f", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Nghiên cứu/ giảng dạy trong các trường đại học/học viện tại Việt Nam và Quốc tế;"}]}]}, "88a6bb36-8111-4154-9867-0aaa400fe5c4": {"id": "88a6bb36-8111-4154-9867-0aaa400fe5c4", "meta": {"align": "left", "depth": 0, "order": 2}, "type": "Paragraph", "value": [{"id": "59ec74d1-0541-443c-804f-cb783ad6305d", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "Chương trình đào tạo Cử nhân ngành Khoa học Máy tính (KHMT) nhằm đào tạo những cử nhân có "}, {"text": "nền tảng khoa học và công nghệ vững chắc, mang tính liên ngành; được phát triển chuyên môn và đổi mới sáng tạo trong các lĩnh vực KHMT; có khả năng học tập suốt đời và thích nghi với thay đổi; có khả năng giao tiếp hiệu quả và hợp tác liên ngành toàn cầu; có trách nhiệm xã hội và đạo đức nghề nghiệp.", "italic": true}]}]}, "8996af4c-83ae-49e0-9f33-7e7f13531683": {"id": "8996af4c-83ae-49e0-9f33-7e7f13531683", "meta": {"align": "left", "depth": 0, "order": 10}, "type": "BulletedList", "value": [{"id": "97348d45-e278-44f4-8143-bbcc5907b9c6", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Khởi nghiệp."}]}]}, "ac5ef4e5-28a8-43d6-b06d-749fcf9044b2": {"id": "ac5ef4e5-28a8-43d6-b06d-749fcf9044b2", "meta": {"align": "left", "depth": 0, "order": 9}, "type": "BulletedList", "value": [{"id": "18d60564-0f11-400d-9d21-db72ade127aa", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Tiếp tục học thạc sĩ/ tiến sĩ. "}]}]}, "b66a7f33-1e08-48d1-b0a0-dfbea9061360": {"id": "b66a7f33-1e08-48d1-b0a0-dfbea9061360", "meta": {"align": "left", "depth": 0, "order": 0}, "type": "HeadingOne", "value": [{"id": "4578829f-ec73-4c3a-94eb-94e7b043ee1e", "type": "heading-one", "props": {"nodeType": "block"}, "children": [{"text": "Mục tiêu đào tạo"}]}]}, "d3a4dd88-8dba-4041-85e7-3151d0fd06d8": {"id": "d3a4dd88-8dba-4041-85e7-3151d0fd06d8", "meta": {"align": "left", "depth": 0, "order": 1}, "type": "Paragraph", "value": [{"id": "0024381d-c15f-4399-a7ae-81913a9b3680", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "Mục tiêu của chương trình đào tạo được xây dựng phù hợp với Tầm nhìn, Sứ mệnh và Triết lý giáo dục của Trường Đại học Tân Tạo; tương thích, phù hợp với Tầm nhìn, Sứ mệnh của Khoa CNTT, nhằm bồi dưỡng con người và phát triển nghiên  cứu khoa học mang tính ứng dụng đáp ứng các nhu cầu xã hội."}]}]}, "d899e93f-6f59-4c25-b02e-ba35e03e5f9b": {"id": "d899e93f-6f59-4c25-b02e-ba35e03e5f9b", "meta": {"align": "left", "depth": 0, "order": 3}, "type": "HeadingTwo", "value": [{"id": "c76bacae-30bf-4764-a20c-d61c1486c017", "type": "heading-two", "props": {"nodeType": "block"}, "children": [{"text": "Vị trí làm việc sau khi tốt nghiệp"}]}]}, "df678ab7-ee4a-4ae2-be54-9443bb2a336f": {"id": "df678ab7-ee4a-4ae2-be54-9443bb2a336f", "meta": {"align": "left", "depth": 0, "order": 5}, "type": "BulletedList", "value": [{"id": "5f697da2-c357-413d-8d6d-4a1bdb46b79b", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Làm việc trong các công ty công nghệ: lập trình viên, kỹ sư phần mềm, trưởng nhóm hoặc giám đốc dự án;"}]}]}, "f6976ca2-3479-4520-ac74-bd8be41fa496": {"id": "f6976ca2-3479-4520-ac74-bd8be41fa496", "meta": {"align": "left", "depth": 0, "order": 6}, "type": "BulletedList", "value": [{"id": "d13f1acf-c12a-4ef2-b781-b0d4745af784", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Kỹ sư dữ liệu/phân tích dữ liệu trong các công ty/tổ chức;"}]}]}}	vi	2026-01-14 14:48:10.25343	2026-01-20 05:35:23.358
95c82101-2a48-4209-bd9c-4e33d39332c7	{"117dff5b-0c90-4c48-9368-a929ae327e76": {"id": "117dff5b-0c90-4c48-9368-a929ae327e76", "meta": {"align": "left", "depth": 0, "order": 10}, "type": "BulletedList", "value": [{"id": "81aed793-cd33-4a09-bbe4-75c305008132", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Khởi nghiệp."}]}]}, "1a2ea206-c24f-4de9-8ab3-ba2d15ddca25": {"id": "1a2ea206-c24f-4de9-8ab3-ba2d15ddca25", "meta": {"align": "left", "depth": 0, "order": 5}, "type": "BulletedList", "value": [{"id": "2b9a7516-111a-4d4f-a47a-b3e29c82ee1b", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Chuyên viên phân tích, thiết kế, cài đặt, kiểm thử, bảo trì các hệ thống khai thác dữ liệu lớn;"}]}]}, "2aaf8fbd-2c0b-4400-9410-2b0a76020edd": {"id": "2aaf8fbd-2c0b-4400-9410-2b0a76020edd", "meta": {"align": "left", "depth": 0, "order": 4}, "type": "Paragraph", "value": [{"id": "3066731a-8c34-4c34-94c8-3e759a31ab9b", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "Sinh viên tốt nghiệp ngành KHDL có thể làm việc ở nhiều vị trí khác nhau, điển hình là các vị trí sau:"}]}]}, "4683316f-684e-4b2c-af7b-03ddf46ee0d8": {"id": "4683316f-684e-4b2c-af7b-03ddf46ee0d8", "meta": {"align": "left", "depth": 0, "order": 9}, "type": "BulletedList", "value": [{"id": "a0b14d90-c4b7-4d60-a582-bd52f9c2a200", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Tiếp tục học thạc sĩ/ tiến sĩ. "}]}]}, "53a1b411-e51a-4f7e-94ad-3111745cbb5a": {"id": "53a1b411-e51a-4f7e-94ad-3111745cbb5a", "meta": {"align": "left", "depth": 0, "order": 2}, "type": "Paragraph", "value": [{"id": "1997a355-3265-461b-b05b-85b2fa831aa2", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "Chương trình đào tạo Cử nhân ngành Khoa học Dữ liệu (KHDL) nhằm đào tạo những cử nhân có "}, {"text": "nền tảng khoa học và công nghệ vững chắc, mang tính liên ngành (Khoa học Máy tính, Toán học và chuyên môn ứng dụng); được phát triển chuyên môn và đổi mới sáng tạo trong lĩnh vực KHDL;  có khả năng học tập suốt đời và thích nghi với thay đổi; có khả năng giao tiếp hiệu quả và hợp tác liên ngành toàn cầu; có trách nhiệm xã hội và đạo đức nghề nghiệp.", "italic": true}]}]}, "79e1d22a-26a1-499a-ac88-a907c01a9438": {"id": "79e1d22a-26a1-499a-ac88-a907c01a9438", "meta": {"align": "left", "depth": 0, "order": 0}, "type": "HeadingTwo", "value": [{"id": "e1bd7128-ad8b-419f-bb71-c4903ca361a8", "type": "heading-two", "props": {"nodeType": "block"}, "children": [{"text": "Mục tiêu đào tạo"}]}]}, "7c29781c-d0dd-4ae5-b4c5-6ae674a4f704": {"id": "7c29781c-d0dd-4ae5-b4c5-6ae674a4f704", "meta": {"align": "left", "depth": 0, "order": 8}, "type": "BulletedList", "value": [{"id": "02a63b16-9228-45e3-b078-d7cbfe873432", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Nghiên cứu/ giảng dạy trong các trường đại học/học viện tại Việt Nam và Quốc tế;"}]}]}, "c0092d87-15fc-4f08-92dd-bcca06d2136e": {"id": "c0092d87-15fc-4f08-92dd-bcca06d2136e", "meta": {"align": "left", "depth": 0, "order": 1}, "type": "Paragraph", "value": [{"id": "f52da46f-7751-4696-a616-ea2f8fd795e4", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "Mục tiêu của chương trình đào tạo được xây dựng phù hợp với Tầm nhìn, Sứ mệnh và Triết lý giáo dục của Trường Đại học Tân Tạo; tương thích, phù hợp với Tầm nhìn, Sứ mệnh của Khoa CNTT, nhằm bồi dưỡng con người và phát triển nghiên cứu khoa học mang tính ứng dụng đáp ứng các nhu cầu xã hội."}]}]}, "cc9b5175-6099-45e3-aa59-343669802ed3": {"id": "cc9b5175-6099-45e3-aa59-343669802ed3", "meta": {"align": "left", "depth": 0, "order": 7}, "type": "BulletedList", "value": [{"id": "876b9edd-370f-4d73-a7c1-9c073a8de696", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Cán bộ quản lý liên quan đến các dự án khai phá và ứng dụng dữ liệu lớn;"}]}]}, "f5c1ab36-1739-40a1-afb7-04d8e10fb04f": {"id": "f5c1ab36-1739-40a1-afb7-04d8e10fb04f", "meta": {"align": "left", "depth": 0, "order": 3}, "type": "HeadingTwo", "value": [{"id": "81fb65d0-0277-4fa7-b553-bc2bb6bd1b63", "type": "heading-two", "props": {"nodeType": "block"}, "children": [{"text": "Vị trí làm việc sau khi tốt nghiệp"}]}]}, "fa435cb8-4624-42b5-a339-899b49e3169b": {"id": "fa435cb8-4624-42b5-a339-899b49e3169b", "meta": {"align": "left", "depth": 0, "order": 6}, "type": "BulletedList", "value": [{"id": "1908dd98-9a24-4edb-b0f3-12a352be17d8", "type": "bulleted-list", "props": {"nodeType": "block"}, "children": [{"text": "Chuyên viên phân tích, xử lý dữ liệu, biến dữ liệu thành giá trị của các cơ quan doanh nghiệp, quản lý, hành chính, thương mại, ngân hàng, tài chính, viễn thông, hàng không, xây dựng..., giúp doanh nghiệp tăng lợi thế cạnh tranh, tăng hiệu quả quản lý và điều hành, tăng lợi nhuận và hiệu quả;"}]}]}}	vi	2026-01-20 05:31:44.992506	2026-01-20 05:36:03.772
