ype": "Paragraph", "value": [{"id": "87b7a620-4a7c-4ed5-acf1-5b0cc5b09b11", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "a/ Ý thức chấp hành các văn bản chỉ đạo của ngành, của cơ quan chỉ đạo cấp trên"}]}]}, "6b3c4505-282b-4387-b0da-eccc419e7a8c": {"id": "6b3c4505-282b-4387-b0da-eccc419e7a8c", "meta": {"depth": 0, "order": 1395}, "type": "Paragraph", "value": [{"id": "a3cde598-69f6-4180-b193-e9085104c286", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "khóa học."}]}]}, "6b4071fd-f482-436b-9b5d-7453858261ef": {"id": "6b4071fd-f482-436b-9b5d-7453858261ef", "meta": {"depth": 0, "order": 1584}, "type": "Paragraph", "value": [{"id": "8c9686ac-5609-4fce-87fe-9d0dc251a94d", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "sẽ trình bày công việc hoàn thành của từng sinh viên để Phòng Học vụ xem xét."}]}]}, "6b69483f-c432-40df-8faf-c1f56b00c847": {"id": "6b69483f-c432-40df-8faf-c1f56b00c847", "meta": {"depth": 0, "order": 1276}, "type": "Paragraph", "value": [{"id": "c8b35137-b09e-4e5d-88e6-71843245e81c", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "a/ Ý thức chấp hành và tham gia tuyên truyền các chủ trương chính sách, pháp luật"}]}]}, "6b878840-779b-4e85-afff-80917859d3b4": {"id": "6b878840-779b-4e85-afff-80917859d3b4", "meta": {"depth": 0, "order": 2541}, "type": "HeadingThree", "value": [{"id": "7abb44c6-f5d6-4686-848e-6acffde5dbae", "type": "heading-three", "props": {"nodeType": "block"}, "children": [{"text": "4.3. Căn cứ vào điều kiện xét và số lượng quy định hằng năm của Quỹ ITA - Vì Tương"}]}]}, "6b904882-1a3a-4ceb-b1f2-7caa6237caa2": {"id": "6b904882-1a3a-4ceb-b1f2-7caa6237caa2", "meta": {"depth": 0, "order": 713}, "type": "Paragraph", "value": [{"id": "4c1b2bab-4f36-4bd1-b6f9-ab3a191edd13", "type": "paragraph", "props": {"nodeType": "block"}, "children": [{"text": "quan chức năng xử"}]}]}, "6bbea696-cc49-4c97-b6ca-5ca9c432f3e4": {"id": "6bbea696-cc